//! A64 decoder, generated by `build.rs` from `a64/a64.inc`.
//!
//! [`decode`] only classifies. Handlers extract their own operand fields and
//! reject reserved field values (for example SBFM with `N != sf`) as UNDEFINED,
//! because the patterns are sometimes looser than the architecture.

include!(concat!(env!("OUT_DIR"), "/a64_decode.rs"));

/// Classifies one instruction word. Encodings that match no pattern come back
/// as [`Op::UnallocatedEncoding`], like the explicit unallocated patterns.
#[inline]
pub fn decode(insn: u32) -> Op {
    let i = ((insn >> 10) & 0x00f) | ((insn >> 18) & 0xff0);
    let (lo, hi) = (
        BUCKETS[i as usize] as usize,
        BUCKETS[i as usize + 1] as usize,
    );
    for &n in &CANDIDATES[lo..hi] {
        let (mask, value, op) = PATTERNS[n as usize];
        if insn & mask == value {
            return op;
        }
    }
    Op::UnallocatedEncoding
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Linear scan over the whole table: what the buckets must reproduce.
    fn decode_slow(insn: u32) -> Op {
        PATTERNS
            .iter()
            .find(|&&(m, v, _)| insn & m == v)
            .map_or(Op::UnallocatedEncoding, |p| p.2)
    }

    #[test]
    fn known_encodings() {
        // Encodings from llvm-mc.
        for (insn, op) in [
            (0x91000c41, Op::ADD_imm),             // add x1, x2, #3
            (0xd503201f, Op::NOP),                 // nop
            (0xd503233f, Op::PACIA_2),             // paciasp (hint space)
            (0xd5032fff, Op::HINT),                // hint #127
            (0xaa0103e0, Op::ORR_shift),           // mov x0, x1
            (0xc8e0fc41, Op::CAS),                 // casal x0, x1, [x2]
            (0xb82103e2, Op::LDADD),               // ldadd w1, w2, [sp]
            (0xa9c10861, Op::STP_LDP_gen),         // ldp x1, x2, [x3, #16]!
            (0xc8007c41, Op::STXR),                // stxr w0, x1, [x2]
            (0x93407c20, Op::SXTW),                // sxtw x0, w1
            (0x9343fc20, Op::ASR_2),               // asr x0, x1, #3
            (0x4f00e420, Op::MOVI),                // movi v0.16b, #1 (dynarmic's "comes first")
            (0xd4000001, Op::SVC),                 // svc #0
            (0xd53b4200, Op::MRS),                 // mrs x0, nzcv
            (0x54000041, Op::B_cond),              // b.ne .+8
            (0x00000000, Op::UnallocatedEncoding), // udf #0
        ] {
            assert_eq!(decode(insn), op, "{insn:#010x}");
        }
    }

    #[test]
    fn buckets_match_linear_scan() {
        // Fixed-seed xorshift over the encoding space, plus every bucket's corner cases.
        let mut x = 0x2545_f491_4f6c_dd1du64;
        for _ in 0..300_000 {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            let insn = x as u32;
            assert_eq!(decode(insn), decode_slow(insn), "{insn:#010x}");
        }
        for &(m, v, _) in PATTERNS.iter() {
            for insn in [v, v | !m] {
                assert_eq!(decode(insn), decode_slow(insn), "{insn:#010x}");
            }
        }
    }
}
